// PROBE ONLY (--probe-layer-tint): tints each zoom level a fixed colour so a screenshot shows which level
// draws the blur. Background red, level 1 yellow, 2 green, 3 blue, 4 purple, higher cyan.
private function cmfProbeTint() : void
{
   var lods:* = this.mcHubMapZoomContainer.mcHubMapContainer.mcLodContainer;
   var tints:Array = [[1,0.3,0.3],[1,1,0.3],[0.3,1,0.3],[0.3,0.3,1],[1,0.3,1],[0.3,1,1]];
   var layer:* = null;
   var tint:Array = null;
   var colour:* = null;
   var lod:int = 0;
   var i:int = 0;
   while(i < lods.numChildren)
   {
      layer = lods.getChildAt(i);
      tint = tints[0];
      lod = lods.GetMinLod();
      while(lod <= lods.GetMaxLod())
      {
         if(lods.GetContainer(lod) == layer) { tint = tints[Math.min(lod,5)]; }
         lod++;
      }
      colour = layer.transform.colorTransform;
      if(colour.redMultiplier != tint[0] || colour.greenMultiplier != tint[1] || colour.blueMultiplier != tint[2])
      {
         colour.redMultiplier = tint[0];
         colour.greenMultiplier = tint[1];
         colour.blueMultiplier = tint[2];
         layer.transform.colorTransform = colour;
      }
      i++;
   }
}

